export declare const dataBlueprintTheme = "/* \u6570\u636E\u84DD\u56FE\uFF1A\u5546\u4E1A\u5206\u6790\u4E0E\u6570\u636E\u590D\u76D8 */\n#wemd {\n  max-width: 677px;\n  margin: 0 auto;\n  padding: 14px 20px;\n  color: #203047;\n  background-color: transparent;\n  font-family: -apple-system, BlinkMacSystemFont, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  font-size: 15px;\n  line-height: 1.72;\n  letter-spacing: 0.006em;\n  font-variant-numeric: tabular-nums;\n  word-break: break-word;\n}\n\n#wemd p {\n  margin: 0 0 18px;\n  color: #203047;\n  font-size: 15px;\n  line-height: 1.72;\n  text-align: left;\n  text-wrap: pretty;\n}\n\n#wemd h1,\n#wemd h2,\n#wemd h3,\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  padding: 0;\n  text-align: left;\n}\n\n#wemd h1 {\n  margin: 18px 0 34px;\n  padding: 27px 24px 25px;\n  border: none;\n  background: #102b4e;\n}\n\n#wemd h1 .content {\n  color: #ffffff;\n  font-size: 29px;\n  font-weight: 800;\n  line-height: 1.38;\n  letter-spacing: 0.015em;\n  text-wrap: balance;\n}\n\n#wemd h2 {\n  margin: 42px 0 20px;\n  padding: 0 0 7px;\n  border-bottom: 2px solid #173f7a;\n  background: transparent;\n}\n\n#wemd h2 .content {\n  color: #173f7a;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 18px;\n  font-weight: 700;\n  line-height: 1.45;\n  text-wrap: balance;\n}\n\n#wemd h3 {\n  margin: 29px 0 14px;\n  padding: 0;\n  border: none;\n}\n\n#wemd h3 .content {\n  display: inline-block;\n  padding: 4px 8px;\n  border: 1px solid #7790ac;\n  color: #173f7a;\n  background: #edf3f8;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 14px;\n  font-weight: 700;\n  text-wrap: balance;\n}\n\n#wemd h4,\n#wemd h5,\n#wemd h6 {\n  margin: 28px 0 13px;\n}\n\n#wemd h4 .content,\n#wemd h5 .content,\n#wemd h6 .content {\n  color: #365777;\n  font-size: 16px;\n  font-weight: 700;\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix,\n#wemd h2 .prefix,\n#wemd h2 .suffix,\n#wemd h3 .prefix,\n#wemd h3 .suffix,\n#wemd h4 .prefix,\n#wemd h4 .suffix,\n#wemd h5 .prefix,\n#wemd h5 .suffix,\n#wemd h6 .prefix,\n#wemd h6 .suffix {\n  display: none;\n}\n\n#wemd blockquote {\n  border: none;\n}\n\n#wemd .multiquote-1,\n#wemd .multiquote-2,\n#wemd .multiquote-3 {\n  margin: 26px 0;\n  padding: 15px 4px;\n  border-top: 1px dashed #7790ac;\n  border-bottom: 1px dashed #7790ac;\n  background: transparent;\n}\n\n#wemd .multiquote-1 p,\n#wemd .multiquote-2 p,\n#wemd .multiquote-3 p {\n  margin: 0;\n  color: #314765;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 14px;\n  line-height: 1.7;\n}\n\n#wemd .multiquote-2,\n#wemd .multiquote-3,\n#wemd .multiquote-1 .multiquote-1 {\n  margin: 10px 0 0;\n  padding: 8px 0 0 12px;\n  border-top: 1px dotted #aebdce;\n  border-bottom: none;\n}\n\n#wemd ul,\n#wemd ol {\n  margin: 18px 0 24px;\n  padding-left: 25px;\n  color: #a84317;\n}\n\n#wemd ul {\n  list-style-type: square;\n}\n\n#wemd ol {\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  list-style-type: decimal-leading-zero;\n}\n\n#wemd li section {\n  margin: 6px 0;\n  color: #203047;\n  font-family: -apple-system, BlinkMacSystemFont, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n  line-height: 1.68;\n}\n\n#wemd ol > li > section {\n  padding: 3px 0 9px;\n  border-bottom: 1px dotted #aebdce;\n}\n\n#wemd a {\n  color: #175da8;\n  font-weight: 600;\n  text-decoration: underline;\n  text-decoration-color: #8bb4df;\n  text-underline-offset: 0.2em;\n}\n\n#wemd strong {\n  color: #142e55;\n  font-weight: 750;\n}\n\n#wemd mark {\n  padding: 1px 4px;\n  color: #633018;\n  background: #f9d9c8;\n}\n\n#wemd hr {\n  height: 0;\n  margin: 38px 0;\n  border: none;\n  border-top: 1px dashed #7790ac;\n  background: transparent;\n}\n\n#wemd figure {\n  margin: 30px 0 36px;\n  break-inside: avoid;\n}\n\n#wemd figure a {\n  border: none;\n}\n\n#wemd img,\n#wemd figure a img {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin: 0 auto;\n  padding: 5px;\n  border: 1px solid #aebdce;\n  background: #ffffff;\n}\n\n#wemd figcaption {\n  margin-top: 0;\n  padding: 8px 10px;\n  color: #536a84;\n  background: #edf3f8;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 11px;\n  line-height: 1.6;\n  text-align: left;\n}\n\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n  padding: 2px 6px;\n  border: 1px solid #c7d2df;\n  color: #174f8f;\n  background: #eef3f8;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n}\n\n#wemd pre {\n  margin: 30px 0;\n  border: 1px solid #173f7a;\n  border-top: 6px solid #a84317;\n  background: #13233a;\n  overflow-x: auto;\n}\n\n#wemd pre code,\n#wemd pre code.hljs {\n  display: block;\n  min-width: max-content;\n  padding: 19px 20px;\n  color: #eaf1f8;\n  background: #13233a;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  line-height: 1.7;\n  white-space: pre;\n}\n\n#wemd pre.custom > .mac-sign {\n  display: block;\n  border-bottom: 1px solid #35506e;\n  background: #13233a;\n}\n\n#wemd .table-container {\n  margin: 32px 0;\n  overflow-x: auto;\n}\n\n#wemd table {\n  width: 100%;\n  border-collapse: collapse;\n  border: 2px solid #173f7a;\n  color: #26354d;\n  background: #ffffff;\n  font-variant-numeric: tabular-nums;\n  text-align: left;\n}\n\n#wemd table tr th,\n#wemd table tr td {\n  min-width: 88px;\n  padding: 11px 10px;\n  border: 1px solid #c9d4e0;\n  font-size: 14px;\n  line-height: 1.6;\n}\n\n#wemd table tr th {\n  color: #ffffff;\n  background: #173f7a;\n  font-weight: 700;\n}\n\n#wemd table tr:nth-child(2n) {\n  background: #f0f4f8;\n}\n\n#wemd .callout {\n  margin: 30px 0;\n  padding: 17px 19px;\n  border: 1px dashed #7790ac;\n  border-radius: 0;\n  color: #26354d;\n  background: transparent;\n  break-inside: avoid;\n}\n\n#wemd .callout-warning,\n#wemd .callout-caution {\n  border-color: #a84317;\n  background: #fff0e8;\n}\n\n#wemd .callout-title {\n  margin-bottom: 7px;\n  color: #173f7a;\n  font-family: \"SFMono-Regular\", Consolas, monospace;\n  font-size: 13px;\n  font-weight: 750;\n}\n\n#wemd .callout p {\n  margin: 0;\n  font-size: 15px;\n}\n\n#wemd .footnote-word,\n#wemd .footnote-ref {\n  color: #175da8;\n  font-weight: 700;\n}\n\n#wemd .footnotes-sep {\n  margin-top: 48px;\n  padding-top: 16px;\n  border-top: 6px solid #173f7a;\n}\n\n#wemd .footnote-item {\n  display: flex;\n  margin-top: 9px;\n}\n\n#wemd .footnote-num {\n  width: 30px;\n  flex-shrink: 0;\n  color: #a84317;\n  font-weight: 700;\n}\n\n#wemd .footnote-item p {\n  margin: 0;\n  color: #5b6e85;\n  font-size: 13px;\n  text-align: left;\n}\n\n#wemd .block-equation {\n  display: block;\n  margin: 30px 0;\n  padding: 18px 10px;\n  border: 1px solid #c9d4e0;\n  background: #f7f9fb;\n  text-align: center;\n  overflow-x: auto;\n}\n\n#wemd .block-equation > svg {\n  max-width: 300% !important;\n}\n\n#wemd .inline-equation > svg {\n  vertical-align: middle;\n}\n\n#wemd pre.mermaid {\n  padding: 20px 10px;\n  border: 1px solid #aebdce;\n  border-top: 6px solid #173f7a;\n  background: #ffffff;\n}\n\n#wemd .task-list-item {\n  display: flex;\n  align-items: flex-start;\n  margin-left: -1.2em;\n  list-style: none;\n}\n\n#wemd .task-list-item input[type='checkbox'] {\n  margin-top: 7px;\n  margin-right: 8px;\n  accent-color: #173f7a;\n  pointer-events: none;\n}\n";
